import { useMemo } from 'react';

interface PasswordStrengthProps {
  password: string;
}

const requirements = [
  { label: 'At least 8 characters', test: (p: string) => p.length >= 8 },
  { label: 'Contains number', test: (p: string) => /\d/.test(p) },
  { label: 'Contains lowercase', test: (p: string) => /[a-z]/.test(p) },
  { label: 'Contains uppercase', test: (p: string) => /[A-Z]/.test(p) },
  { label: 'Contains symbol', test: (p: string) => /[!@#$%^&*]/.test(p) },
];

export function PasswordStrength({ password }: PasswordStrengthProps) {
  const { strength, passed } = useMemo(() => {
    const results = requirements.map(r => r.test(password));
    const passedCount = results.filter(Boolean).length;
    return {
      strength: passedCount <= 2 ? 'weak' : passedCount <= 4 ? 'medium' : 'strong',
      passed: results,
    };
  }, [password]);

  const colors = { weak: 'bg-red-500', medium: 'bg-yellow-500', strong: 'bg-green-500' };
  const widths = { weak: 'w-1/3', medium: 'w-2/3', strong: 'w-full' };

  return (
    <div className="mt-2">
      <div className="h-2 bg-gray-200 rounded">
        <div className={`h-full rounded ${colors[strength]} ${widths[strength]} transition-all`} />
      </div>
      <p className="text-sm mt-1 capitalize">{strength}</p>
      <ul className="mt-2 text-sm space-y-1">
        {requirements.map((req, i) => (
          <li key={i} className={passed[i] ? 'text-green-600' : 'text-gray-500'}>
            {passed[i] ? '✓' : '○'} {req.label}
          </li>
        ))}
      </ul>
    </div>
  );
}
