import { useMutation, useQueryClient } from '@tanstack/react-query';

export function useBookmark(articleId: string, isBookmarked: boolean) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const method = isBookmarked ? 'DELETE' : 'POST';
      await fetch(`/api/articles/${articleId}/bookmark`, { method });
    },
    onMutate: async () => {
      await queryClient.cancelQueries({ queryKey: ['articles'] });
      const previous = queryClient.getQueryData(['articles']);

      queryClient.setQueryData(['articles'], (old: any) =>
        old?.map((a: any) =>
          a.id === articleId
            ? { ...a, isBookmarked: !isBookmarked, bookmarkCount: a.bookmarkCount + (isBookmarked ? -1 : 1) }
            : a
        )
      );

      return { previous };
    },
    onError: (err, vars, context) => {
      queryClient.setQueryData(['articles'], context?.previous);
    },
  });
}
