**cache.ts**
```typescript
interface CacheEntry {
  data: any;
  expiresAt: number;
  size: number;
}

class LRUCache {
  private cache = new Map<string, CacheEntry>();
  private accessOrder: string[] = [];
  private currentSize = 0;
  private maxSize: number;
  private defaultTtl: number;

  constructor(maxSize = 10 * 1024 * 1024, defaultTtl = 5 * 60 * 1000) {
    this.maxSize = maxSize;
    this.defaultTtl = defaultTtl;
  }

  private generateKey(url: string, params?: Record<string, any>): string {
    const sortedParams = params ? JSON.stringify(Object.entries(params).sort()) : '';
    return `${url}:${sortedParams}`;
  }

  get(url: string, params?: Record<string, any>): any | null {
    const key = this.generateKey(url, params);
    const entry = this.cache.get(key);

    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.delete(key);
      return null;
    }

    // Update access order
    this.accessOrder = this.accessOrder.filter(k => k !== key);
    this.accessOrder.push(key);

    return entry.data;
  }

  set(url: string, data: any, params?: Record<string, any>, ttl = this.defaultTtl): void {
    const key = this.generateKey(url, params);
    const size = JSON.stringify(data).length;

    // Evict if needed
    while (this.currentSize + size > this.maxSize && this.accessOrder.length > 0) {
      const oldest = this.accessOrder.shift()!;
      this.delete(oldest);
    }

    this.cache.set(key, { data, expiresAt: Date.now() + ttl, size });
    this.accessOrder.push(key);
    this.currentSize += size;
  }

  invalidate(pattern: string): void {
    for (const key of this.cache.keys()) {
      if (key.startsWith(pattern)) {
        this.delete(key);
      }
    }
  }

  private delete(key: string): void {
    const entry = this.cache.get(key);
    if (entry) {
      this.currentSize -= entry.size;
      this.cache.delete(key);
      this.accessOrder = this.accessOrder.filter(k => k !== key);
    }
  }
}

export const apiCache = new LRUCache();
```

**api.ts update**
```typescript
import { apiCache } from './cache';

const cacheConfig: Record<string, { ttl: number }> = {
  '/api/products': { ttl: 10 * 60 * 1000 },
  '/api/categories': { ttl: 30 * 60 * 1000 },
};

export async function api<T>(url: string, options: RequestInit = {}): Promise<T> {
  const method = options.method?.toUpperCase() || 'GET';

  if (method === 'GET') {
    const cached = apiCache.get(url);
    if (cached) return cached as T;
  }

  const response = await fetch(url, options);
  const data = await response.json();

  if (method === 'GET') {
    const config = cacheConfig[url];
    apiCache.set(url, data, undefined, config?.ttl);
  } else {
    // Invalidate related cache
    const basePath = url.split('/').slice(0, -1).join('/');
    apiCache.invalidate(basePath);
  }

  return data;
}
```

