import { useState, useEffect } from 'react';
import { X } from 'lucide-react';

interface Announcement {
  id: string;
  text: string;
  link?: { url: string; label: string };
  type: 'info' | 'warning' | 'success';
}

export function AnnouncementBanner() {
  const [announcement, setAnnouncement] = useState<Announcement | null>(null);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    fetch('/api/announcements/active')
      .then(r => r.json())
      .then(data => {
        if (data) {
          const dismissedIds = JSON.parse(localStorage.getItem('dismissedAnnouncements') || '[]');
          if (!dismissedIds.includes(data.id)) {
            setAnnouncement(data);
          }
        }
      });
  }, []);

  const handleDismiss = () => {
    if (announcement) {
      const dismissedIds = JSON.parse(localStorage.getItem('dismissedAnnouncements') || '[]');
      localStorage.setItem('dismissedAnnouncements', JSON.stringify([...dismissedIds, announcement.id]));
    }
    setDismissed(true);
  };

  if (!announcement || dismissed) return null;

  const colors = {
    info: 'bg-blue-600',
    warning: 'bg-yellow-500',
    success: 'bg-green-600',
  };

  return (
    <div className={`${colors[announcement.type]} text-white px-4 py-2`}>
      <div className="container mx-auto flex items-center justify-between">
        <p className="flex-1 text-center">
          {announcement.text}
          {announcement.link && (
            <a href={announcement.link.url} className="ml-2 underline font-medium">
              {announcement.link.label}
            </a>
          )}
        </p>
        <button onClick={handleDismiss} aria-label="Dismiss announcement">
          <X className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
}
```

