import { useInfiniteQuery } from '@tanstack/react-query';
import { formatDistanceToNow } from 'date-fns';
import { MessageSquare, Heart, UserPlus, Edit, Trash } from 'lucide-react';

const activityIcons = {
  comment: MessageSquare,
  like: Heart,
  follow: UserPlus,
  edit: Edit,
  delete: Trash,
};

const activityColors = {
  comment: 'bg-blue-100 text-blue-600',
  like: 'bg-red-100 text-red-600',
  follow: 'bg-green-100 text-green-600',
  edit: 'bg-yellow-100 text-yellow-600',
  delete: 'bg-gray-100 text-gray-600',
};

export function ActivityTimeline({ userId }: { userId: string }) {
  const [filter, setFilter] = useState<string | null>(null);

  const { data, fetchNextPage, hasNextPage, isFetchingNextPage } = useInfiniteQuery({
    queryKey: ['activity', userId, filter],
    queryFn: ({ pageParam }) =>
      fetch(`/api/users/${userId}/activity?cursor=${pageParam || ''}&type=${filter || ''}`)
        .then(r => r.json()),
    getNextPageParam: (lastPage) => lastPage.nextCursor,
    initialPageParam: '',
  });

  const activities = data?.pages.flatMap(p => p.items) || [];

  return (
    <div>
      <div className="flex gap-2 mb-4">
        <button
          onClick={() => setFilter(null)}
          className={!filter ? 'font-bold' : ''}
        >
          All
        </button>
        {Object.keys(activityIcons).map(type => (
          <button
            key={type}
            onClick={() => setFilter(type)}
            className={filter === type ? 'font-bold' : ''}
          >
            {type}
          </button>
        ))}
      </div>

      <div className="space-y-4">
        {activities.map((activity, i) => {
          const Icon = activityIcons[activity.type] || MessageSquare;
          return (
            <div key={activity.id} className="flex gap-3">
              <div className="relative">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${activityColors[activity.type]}`}>
                  <Icon className="w-5 h-5" />
                </div>
                {i < activities.length - 1 && (
                  <div className="absolute top-10 left-1/2 w-0.5 h-full -translate-x-1/2 bg-gray-200" />
                )}
              </div>
              <div className="flex-1 pb-4">
                <p>{activity.description}</p>
                <p className="text-sm text-gray-500">
                  {formatDistanceToNow(new Date(activity.createdAt), { addSuffix: true })}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {hasNextPage && (
        <button
          onClick={() => fetchNextPage()}
          disabled={isFetchingNextPage}
          className="w-full py-2 text-blue-600"
        >
          {isFetchingNextPage ? 'Loading...' : 'Load more'}
        </button>
      )}
    </div>
  );
}
