import { useCompare } from '@/hooks/useCompare';
import { useCart } from '@/context/CartContext';
import { useQueries } from '@tanstack/react-query';

const comparisonFields = [
  { key: 'price', label: 'Price', format: (v: number) => `$${v}` },
  { key: 'rating', label: 'Rating' },
  { key: 'specs.weight', label: 'Weight' },
  { key: 'specs.dimensions', label: 'Dimensions' },
  { key: 'specs.battery', label: 'Battery Life' },
];

export function Compare() {
  const { items, removeItem, clear } = useCompare();
  const { addToCart } = useCart();

  const productQueries = useQueries({
    queries: items.map(id => ({
      queryKey: ['product', id],
      queryFn: () => fetch(`/api/products/${id}`).then(r => r.json()),
    })),
  });

  const products = productQueries.map(q => q.data).filter(Boolean);

  const getValue = (product: any, path: string) => {
    return path.split('.').reduce((obj, key) => obj?.[key], product);
  };

  const isDifferent = (field: string) => {
    const values = products.map(p => getValue(p, field));
    return new Set(values).size > 1;
  };

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead className="sticky top-0 bg-white z-10">
          <tr>
            <th className="p-4">Feature</th>
            {products.map(product => (
              <th key={product.id} className="p-4">
                <img src={product.image} className="w-20 h-20 mx-auto" />
                <p className="font-semibold">{product.name}</p>
                <button onClick={() => removeItem(product.id)} className="text-red-500 text-sm">
                  Remove
                </button>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {comparisonFields.map(field => (
            <tr key={field.key} className={isDifferent(field.key) ? 'bg-yellow-50' : ''}>
              <td className="p-4 font-medium">{field.label}</td>
              {products.map(product => (
                <td key={product.id} className="p-4 text-center">
                  {field.format
                    ? field.format(getValue(product, field.key))
                    : getValue(product, field.key) || '-'}
                </td>
              ))}
            </tr>
          ))}
          <tr>
            <td className="p-4">Actions</td>
            {products.map(product => (
              <td key={product.id} className="p-4 text-center">
                <button
                  onClick={() => addToCart(product)}
                  className="px-4 py-2 bg-blue-500 text-white rounded"
                >
                  Add to Cart
                </button>
              </td>
            ))}
          </tr>
        </tbody>
      </table>
      <button onClick={clear} className="mt-4 text-gray-500">Clear all</button>
    </div>
  );
}
```

